sys_script_include.script:
var InventoryAssignUpdate = Class.create();
InventoryAssignUpdate.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
	updateAssign: function(){
		var computer_id = this.getParameter('sysparm_com_id');
		var inventory = new GlideRecord('x_1756012_servic_0_inventory');
		inventory.addQuery('computer_id', computer_id);
		inventory.query();

		if(inventory.next()) {
			inventory.assign_status = 'received';
			inventory.update();
			return true;
		}
		return false;
	},
    type: 'InventoryAssignUpdate'
});
